// Reading endurance index — record JAH-GGN-EREADER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"battery_weeks": 6, "storage_gb": 32, "price_usd": 150};
var value = (m.battery_weeks*m.storage_gb/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-EREADER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-EREADER-000001|' + value.toFixed(2) + ' endurance index');

